    TEST_ASSERT_EQUAL_STRING("1.4865%", ip("'<percentage>'", "-38.567%", "41.54%", 5000, 2));
    TEST_ASSERT_EQUAL_STRING("705.55", ip("'<length-percentage>+ | <number>'", "440", "971.1", 5000, 2));
